// === Tab: mySketch ===
let cols;
let rows;
let side = 100;
let t = 0;
let v;
function setup(){
createCanvas(600, 600);
cols = width/side;
rows = height/side;

}

function draw(){
background(50);
stroke(190);
strokeWeight(5);

v = 10*sin(t);
for(i = -1; i < cols + 1; i++){
  for(j = -1; j < rows + 1; j ++){
  fill(255*i/cols, 255*j/rows, 50);
  //rect(xpos(i), ypos(j), xpos(i+1)-xpos(i), ypos(j+1)-ypos(j));
  quad(xpos(i), ypos(j), xpos(i+1), ypos(j), xpos(i+1), ypos(j+1), xpos(i), ypos(j+1));


  }

}

t = t + 0.01;


}

function xpos(x){

return x*side + v*random(-1,1);

}

function ypos(y){

return y*side + v*random(-1,1);




}

